import os.path

from server.storage.neural import NeuralWriter, NeuralReader


def column_assertion(df, col_select, expected_val):

    found = df[col_select].iloc[0]
    msg = f"Column {', '.join(col_select)} was not placed correctly! (found {found}, expected {expected_val})"

    assert found == expected_val, msg


def test_neural_column_placement():

    base = r'data\neural_place'
    out = os.path.join(base, 'output.h5')
    os.remove(out)
    writer = NeuralWriter.from_sources(
        os.path.join(base, 'rcs_left_1637208257237_1637208258233.csv'),
        os.path.join(base, 'rcs_right_1637208257237_1637208258233.csv'),
        out
    )
    writer.load()
    writer.write()

    reader = NeuralReader(out)
    read_df = reader.read()

    column_assertion(read_df, ('Left', 'STN', 'CH 1'), 0.1)
    column_assertion(read_df, ('Left', 'STN', 'CH 2'), 0.3)
    column_assertion(read_df, ('Left', 'M1', 'CH 1'), 0.5)
    column_assertion(read_df, ('Left', 'M1', 'CH 2'), 0.7)
    column_assertion(read_df, ('Right', 'STN', 'CH 1'), 0.2)
    column_assertion(read_df, ('Right', 'STN', 'CH 2'), 0.4)
    column_assertion(read_df, ('Right', 'M1', 'CH 1'), 0.6)
    column_assertion(read_df, ('Right', 'M1', 'CH 2'), 0.8)


if __name__ == "__main__":
    test_neural_column_placement()
